import{_ as e,c as i,o as r,a2 as l}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"隱私權政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy.md","filePath":"zh-TW/guide/privacy.md","lastUpdated":1793163976000}'),t={name:"zh-TW/guide/privacy.md"};function o(n,a,s,p,h,u){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="隱私權政策" tabindex="-1">隱私權政策 <a class="header-anchor" href="#隱私權政策" aria-label="Permalink to &quot;隱私權政策&quot;">​</a></h1><p>NueZip 以完全離線優先（offline-first）的應用程式為設計理念。您的隱私是我們的首要考量。</p><h2 id="僅限本機的設計" tabindex="-1">僅限本機的設計 <a class="header-anchor" href="#僅限本機的設計" aria-label="Permalink to &quot;僅限本機的設計&quot;">​</a></h2><ul><li>所有壓縮檔操作 — 壓縮、解壓縮、轉換、加密 — 完全在您的 Mac 上執行。</li><li>NueZip 不會將您的檔案或資料上傳到任何外部伺服器。</li><li>使用本 App 不需要帳號或註冊。</li><li>一般操作不需要網際網路連線。</li></ul><h2 id="我們不蒐集的項目" tabindex="-1">我們不蒐集的項目 <a class="header-anchor" href="#我們不蒐集的項目" aria-label="Permalink to &quot;我們不蒐集的項目&quot;">​</a></h2><ul><li>我們不會蒐集您的檔案、文件或壓縮檔內容。</li><li>我們不會追蹤您的活動、瀏覽行為或使用模式。</li><li>我們不會傳送任何檔案中繼資料或個人資訊到外部伺服器。</li><li>我們不包含第三方的分析、廣告或追蹤 SDK。</li><li>我們沒有任何遙測系統。</li></ul><h2 id="本機儲存的資料" tabindex="-1">本機儲存的資料 <a class="header-anchor" href="#本機儲存的資料" aria-label="Permalink to &quot;本機儲存的資料&quot;">​</a></h2><p>以下資料僅儲存在您的裝置上：</p><ul><li><strong>App 設定</strong>：主題、語言偏好、壓縮偏好</li><li><strong>授權金鑰</strong>：若已購買（安全地儲存在本機鑰匙圈中）</li><li><strong>最近檔案清單</strong>：最近開啟的壓縮檔，方便快速存取</li><li><strong>密碼記錄</strong>：若您選擇儲存，會保存在本機鑰匙圈中</li><li><strong>日誌</strong>：用於疑難排解的除錯日誌（可隨時刪除）</li></ul><h2 id="app-使用的權限" tabindex="-1">App 使用的權限 <a class="header-anchor" href="#app-使用的權限" aria-label="Permalink to &quot;App 使用的權限&quot;">​</a></h2><ul><li><strong>檔案與資料夾</strong>：讀取壓縮檔檔案與解壓縮內容所需。</li><li><strong>Finder 擴充功能</strong>：選用，在 Finder 中新增右鍵選單項目。</li><li><strong>通知</strong>：選用，用於長時間執行任務的完成提醒。</li></ul><p>您可以隨時在 <strong>系統設定 → 隱私權與安全性</strong> 中管理這些權限。</p><h2 id="應用程式內購買-授權" tabindex="-1">應用程式內購買 / 授權 <a class="header-anchor" href="#應用程式內購買-授權" aria-label="Permalink to &quot;應用程式內購買 / 授權&quot;">​</a></h2><p>授權購買由 Apple 透過 Mac App Store 處理。NueZip 不會收到或儲存您的付款資訊。授權收據會儲存在本機以驗證所有權。</p><h2 id="第三方服務" tabindex="-1">第三方服務 <a class="header-anchor" href="#第三方服務" aria-label="Permalink to &quot;第三方服務&quot;">​</a></h2><p>NueZip 不包含任何第三方的分析、廣告或追蹤服務。本 App 完全自給自足。</p><h2 id="隱私權要求" tabindex="-1">隱私權要求 <a class="header-anchor" href="#隱私權要求" aria-label="Permalink to &quot;隱私權要求&quot;">​</a></h2><p>由於 NueZip 將所有資料儲存在您裝置的本機上，我們的伺服器中並未持有任何個人資料。若您對隱私有任何疑問，請聯絡我們。</p><h2 id="聯絡方式" tabindex="-1">聯絡方式 <a class="header-anchor" href="#聯絡方式" aria-label="Permalink to &quot;聯絡方式&quot;">​</a></h2><p>有隱私相關疑問，請在 <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 開立 issue 或來信與我們聯絡。</p>',20)])])}const g=e(t,[["render",o]]);export{c as __pageData,g as default};
